import type { SystemUser } from './system-user-model';

export const CTSProjectStatusKeyToLabel = {
  'Planning': 'Planning',
  'Active': 'Active',
  'OnHold': 'On Hold',
  'Completed': 'Completed',
  'Cancelled': 'Cancelled'
} as const;
export type CTSProjectStatusKey = keyof typeof CTSProjectStatusKeyToLabel;

export interface CTSProject {
  /**
   * @displayName CTS Project
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Project Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  projectName: string;
  /**
   * @displayName Description
   */
  description?: string;
  /**
   * @displayName End Date
   */
  endDate?: string;
  /**
   * @displayName Location
   */
  location?: string;
  /**
   * @displayName Progress
   */
  progress?: number;
  /**
   * @displayName Project Code
   * @validationRule Required for create/update operations
   */
  projectCode: string;
  /**
   * @displayName Project Manager
   */
  projectManager?: Pick<SystemUser, 'id' | 'fullName'>;
  /**
   * @displayName Start Date
   */
  startDate?: string;
  /**
   * @displayName Status
   */
  statusKey?: CTSProjectStatusKey;
}

export const _CTSProject = 'CTSProject' as const;